99	// Function words that would otherwise crowd every ranking. The list is
100	// deliberately short and fixed: callers who need a different list can filter
101	// the full ranking (pass a large n) themselves.
102	const STOP_WORDS = new Set([
103	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
104	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
105	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
106	  'will', 'with',
107	]);
108	
109	/**
110	 * List the most frequent words in a piece of text.
111	 *
112	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
113	 * and stop words are skipped. Entries are ordered by count (highest first),
114	 * then alphabetically, so the result is deterministic.
115	 *
116	 * @param {string} text
117	 * @param {number} n How many entries to return; a non-negative integer.
118	 * @returns {Array<{word: string, count: number}>}
119	 */
120	function topWords(text, n) {
121	  assertText('topWords', text);
122	  if (!Number.isInteger(n) || n < 0) {
123	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
124	  }
125	  const counts = new Map();
126	  for (const token of tokenize(text)) {
127	    const word = token.toLowerCase().replace(/’/g, "'");
128	    if (STOP_WORDS.has(word)) {
129	      continue;
130	    }
131	    counts.set(word, (counts.get(word) ?? 0) + 1);
132	  }
133	  return [...counts]
134	    .map(([word, count]) => ({ word, count }))
135	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
136	    .slice(0, n);
137	}
